<?php require_once "../db.php"; require_role("Student"); $r=$conn->query("SELECT * FROM quiz ORDER BY id DESC"); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Available Quizzes</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/student_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><h2 class="fw-bold">Available Quizzes</h2><p class="text-muted">Choose a quiz and start your examination.</p><div class="row g-4"><?php while($q=$r->fetch_assoc()):?><div class="col-md-6 col-xl-4"><div class="card panel-card h-100 p-3"><span class="badge bg-primary align-self-start"><?=e($q["subject"])?></span><h4 class="fw-bold mt-3"><?=e($q["title"])?></h4><p class="text-muted"><?=e($q["description"])?></p><div class="small text-muted mb-3"><i class="bi bi-question-circle"></i> <?=count_questions($conn,$q["id"])?> Questions &nbsp; <i class="bi bi-clock"></i> <?=$q["duration"]?> Min</div><a href="take_quiz.php?id=<?=$q["id"]?>" class="btn btn-primary w-100">Start Quiz <i class="bi bi-arrow-right"></i></a></div></div><?php endwhile;?></div></div></main></div></div></body></html>
<?php function count_questions($conn,$id){$s=$conn->prepare("SELECT COUNT(*) c FROM questions WHERE quiz_id=?");$s->bind_param("i",$id);$s->execute();return (int)$s->get_result()->fetch_assoc()["c"];} ?>
